/* lcdcon.c - the translator's log on the fx-CP400 panel (see lcdcon.h).
 *
 * The panel is the DCS controller the display driver talks to
 * (bsp/classpad/SRC/INC/classpad_lcd.h): 16-bit data port 0xB4000000, RS on
 * Port R bit 4, CASET/PASET windows with four parameter writes, RAMWR, one
 * RGB565 pixel per write; SLPOUT and DISPON before anything shows. Casio's
 * OS leaves the panel awake, casio-emu starts it asleep, so the first use
 * wakes it. Text goes in the top LINES*CELL_H rows, 40 columns of a 4x8
 * font drawn 2x (rt/lcdfont.h, generated by tools/bdf2font.py), scrolling.
 * Every byte also lands in a text ring, drawn or not, so a halt can show the
 * last lines printed after the hand-over.
 *
 * Hand-over: the display driver's sign-on "CLASSPAD DDI:" (classpad_ddi.cpp)
 * follows its PanelInit and precedes its first push, so from that string on
 * nothing is drawn (a window command of ours between two of the driver's
 * pixel writes would move its cursor). dbt_halt takes the panel back: the
 * kernel is dead then and the driver will never push again. */
#ifdef DBT_LCD_CONSOLE
#include "rt.h"
#include "lcdcon.h"
#include "lcdfont.h"

#define PORT   (*(volatile sf_u16 *)0xB4000000u)
#define PRDR   (*(volatile sf_u8 *)0xA405013Cu)
#define SCALE  2
#define CELL_W (LCDFONT_W * SCALE)     /* 8 */
#define CELL_H (LCDFONT_H * SCALE)     /* 16 */
#define COLS   (320 / CELL_W)          /* 40 */
#define LINES  6                       /* rows 0..95 */
#define FG     0xFFFFu
#define BG     0x0000u

static char   g_text[LINES][COLS];
static int    g_col, g_line;
static int    g_state;                 /* 0 untouched, 1 drawing, 2 handed over, 3 halted (drawing again) */
static int    g_match;                 /* bytes of the hand-over string matched so far */
static const char g_handover[] = "CLASSPAD DDI:";

static void cmd(unsigned c)  { PRDR = (sf_u8)(PRDR & ~0x10u); PORT = (sf_u16)c; PRDR = (sf_u8)(PRDR | 0x10u); }
static void dat(unsigned v)  { PORT = (sf_u16)v; }
static void delay(unsigned n) { volatile unsigned i; for (i = 0; i < n; i++) ; }

static void window(unsigned x0, unsigned x1, unsigned y0, unsigned y1)
{
    cmd(0x2A); dat(x0 >> 8); dat(x0 & 0xFF); dat(x1 >> 8); dat(x1 & 0xFF);     /* CASET */
    cmd(0x2B); dat(y0 >> 8); dat(y0 & 0xFF); dat(y1 >> 8); dat(y1 & 0xFF);     /* PASET */
    cmd(0x2C);                                                                 /* RAMWR */
}

static void panel_wake(void)
{
    cmd(0x11);                          /* SLPOUT: 120 ms before the next command */
    delay(3000000);
    cmd(0x3A); dat(0x55);               /* COLMOD 16 bpp */
}

static void clear_region(void)
{
    unsigned n;
    window(0, 319, 0, LINES * CELL_H - 1);
    for (n = 0; n < 320u * LINES * CELL_H; n++) dat(BG);
}

static void draw_cell(int line, int col, char ch)
{
    const unsigned char *g = lcdfont[(ch >= 32 && ch < 127) ? ch - 32 : 0];
    int y, sy, x, sx;
    window((unsigned)(col * CELL_W), (unsigned)(col * CELL_W + CELL_W - 1),
           (unsigned)(line * CELL_H), (unsigned)(line * CELL_H + CELL_H - 1));
    for (y = 0; y < LCDFONT_H; y++)
        for (sy = 0; sy < SCALE; sy++)
            for (x = 0; x < LCDFONT_W; x++) {
                unsigned px = (g[y] & (0x80u >> x)) ? FG : BG;
                for (sx = 0; sx < SCALE; sx++) dat(px);
            }
}

static void draw_all(void)
{
    int l, c;
    for (l = 0; l < LINES; l++)
        for (c = 0; c < COLS; c++) draw_cell(l, c, g_text[l][c]);
}

static int drawing(void) { return g_state == 1 || g_state == 3; }

static void newline(void)
{
    g_col = 0;
    if (g_line < LINES - 1) { g_line++; return; }
    {   /* scroll the text up one line */
        int l, c;
        for (l = 1; l < LINES; l++)
            for (c = 0; c < COLS; c++) g_text[l - 1][c] = g_text[l][c];
        for (c = 0; c < COLS; c++) g_text[LINES - 1][c] = ' ';
    }
    if (drawing()) draw_all();
}

static void first_use(void)
{
    int l, c;
    for (l = 0; l < LINES; l++) for (c = 0; c < COLS; c++) g_text[l][c] = ' ';
    g_col = g_line = 0;
    panel_wake();
    clear_region();
    cmd(0x29);                          /* DISPON */
    g_state = 1;
}

void lcdcon_putc(int c)
{
    if (g_state == 0) first_use();
    /* the display driver's sign-on: hand the panel over */
    if (g_state == 1) {
        if ((char)c == g_handover[g_match]) { if (!g_handover[++g_match]) g_state = 2; }
        else g_match = ((char)c == g_handover[0]) ? 1 : 0;
    }
    if (c == '\n') { newline(); return; }
    if (c == '\r') return;
    if (c < 32 || c > 126) c = '?';
    if (g_col >= COLS) newline();
    g_text[g_line][g_col] = (char)c;
    if (drawing()) draw_cell(g_line, g_col, (char)c);
    g_col++;
}

static void reg(const char *name, sf_u32 v) { dbt_puts(name); dbt_puthex(v); dbt_putc(' '); }

void lcdcon_halt(const char *why)
{
    const dbt_gctx *x = &dbt_ctx_exc;
    int i;
    (void)why;                          /* dbt_halt prints it after this returns */
    if (g_state == 0) { int l, c; for (l = 0; l < LINES; l++) for (c = 0; c < COLS; c++) g_text[l][c] = ' '; }
    g_state = 3;
    panel_wake();
    clear_region();
    draw_all();
    cmd(0x29);
    /* the last exception the translator saw (the one that led here, usually) */
    dbt_puts("\nlast exc: ");
    reg("EXPEVT=", x->expevt); reg("TEA=", x->tea); reg("INTEVT=", x->intevt); dbt_putc('\n');
    reg("hostSPC=", x->host_spc); reg("SSR=", x->ssr); reg("SR=", x->sr); reg("PR=", x->pr); dbt_putc('\n');
    for (i = 0; i < 16; i++) {
        dbt_putc('r'); if (i >= 10) dbt_putc('1'); dbt_putc((char)('0' + i % 10)); dbt_putc('=');
        dbt_puthex(x->r[i]); dbt_putc((i % 4 == 3) ? '\n' : ' ');
    }
}
#else
typedef int lcdcon_not_built;          /* keep the translation unit non-empty */
#endif
